node -e "
const lat1 = 37.7749, lon1 = -122.4194;  // San Francisco
const lat2 = 42.3396, lon2 = -71.0693;   // Boston, MA 02118

const R = 6371; // Earth's radius in km
const dLat = (lat2 - lat1) * Math.PI / 180;
const dLon = (lon2 - lon1) * Math.PI / 180;
const a = Math.sin(dLat/2)**2 +
          Math.cos(lat1 * Math.PI/180) * Math.cos(lat2 * Math.PI/180) *
          Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));
const distKm = R * c;
const distMiles = distKm * 0.621371;

console.log('=== Distance Calculation ===');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('       (approx. 42.3396, -71.0693)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + distMiles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
"
